import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { planJobs } from '../job-plan.js';

const job = (id, deps = [], state = 'pending') => ({ id, deps, state });

test('full graph ordering includes completed jobs before filtering', () => {
  const spec = [job('a', ['z']), job('b'), job('z', [], 'succeeded')];
  assert.deepEqual(planJobs(spec), { order: ['b', 'a'], ready: ['a', 'b'], blocked: [] });
  assert.deepEqual(planJobs(spec.toReversed ? spec.toReversed() : [...spec].reverse()), planJobs(spec));
});

test('all failed ancestry survives failed and succeeded intermediates', () => {
  assert.deepEqual(planJobs([
    job('z', [], 'failed'), job('a', ['z'], 'failed'),
    job('s', ['a'], 'succeeded'), job('p', ['s', 'z']), job('q', ['p']),
  ]), {
    order: [], ready: [], blocked: [
      { id: 'p', causes: ['a', 'z'] }, { id: 'q', causes: ['a', 'z'] },
    ],
  });
});

test('IDs use exact code-unit ordering and input is not mutated', () => {
  const ids = ['__proto__', 'constructor', 'é', 'e\u0301', '😀', '\uE000', ' ', 'Z', 'a'];
  const spec = ids.map(id => Object.freeze({ ...job(id), deps: Object.freeze([]), ignored: true }));
  Object.freeze(spec);
  const expected = [...ids].sort((a, b) => a < b ? -1 : a > b ? 1 : 0);
  assert.deepEqual(planJobs(spec), { order: expected, ready: expected, blocked: [] });
  assert.deepEqual(planJobs([job('__proto__', [], 'failed'), job('constructor', ['__proto__'])]), {
    order: [], ready: [], blocked: [{ id: 'constructor', causes: ['__proto__'] }],
  });
});

test('ready uses current direct dependency states', () => {
  assert.deepEqual(planJobs([job('a'), job('b', ['a']), job('c', [], 'succeeded'), job('d', ['c'])]), {
    order: ['a', 'b', 'd'], ready: ['a', 'd'], blocked: [],
  });
});

test('malformed inputs and cycles in every state are rejected', () => {
  const invalid = [null, {}, '[]', [null], [[]], [1], [{}],
    [job('')], [job(1)], [job('a', null)], [job('a', 'b')],
    [job('a', [null])], [job('a', [''])], [job('a', [1])],
    [job('a', [], 'Pending')], [job('a', [], null)],
    [job('a'), job('a')], [job('a', ['b'])],
    [job('a'), job('b', ['a', 'a'])], [job('a', ['a'])],
    [job('a', ['b'], 'succeeded'), job('b', ['a'], 'failed')],
    [job('ok'), job('a', ['b'], 'failed'), job('b', ['a'], 'failed')],
  ];
  for (const spec of invalid) assert.throws(() => planJobs(spec), Error);
  assert.throws(() => planJobs(new Array(1)), Error);
  assert.throws(() => planJobs([job('a', new Array(1))]), Error);
});

test('long dependency chains do not require recursion', () => {
  const spec = Array.from({ length: 15000 }, (_, i) => job(String(i), i ? [String(i - 1)] : []));
  const result = planJobs(spec);
  assert.deepEqual(result.order, spec.map(j => j.id));
  assert.deepEqual(result.ready, ['0']);
});

test('CLI succeeds cleanly, rejects errors, and stays silent on import', () => {
  const directory = mkdtempSync(join(tmpdir(), 'job-plan-'));
  const cli = fileURLToPath(new URL('../job-plan.js', import.meta.url));
  const run = args => spawnSync(process.execPath, args, { encoding: 'utf8' });
  try {
    const valid = join(directory, 'valid.json');
    writeFileSync(valid, JSON.stringify([job('é')]));
    const success = run([cli, valid]);
    assert.equal(success.status, 0);
    assert.equal(success.stderr, '');
    assert.equal(success.stdout, '{"order":["é"],"ready":["é"],"blocked":[]}\n');
    const invalidJson = join(directory, 'invalid.json');
    writeFileSync(invalidJson, '{');
    const invalidGraph = join(directory, 'graph.json');
    writeFileSync(invalidGraph, JSON.stringify([job('x', ['x'], 'succeeded')]));
    for (const args of [[cli], [cli, valid, valid], [cli, join(directory, 'missing')],
      [cli, directory], [cli, invalidJson], [cli, invalidGraph]]) {
      const result = run(args);
      assert.equal(result.status, 2);
      assert.equal(result.stdout, '');
      assert.ok(result.stderr.length > 0);
    }
    const imported = run(['--input-type=module', '-e', `import ${JSON.stringify(new URL('../job-plan.js', import.meta.url).href)}`]);
    assert.equal(imported.status, 0);
    assert.equal(imported.stdout, '');
    assert.equal(imported.stderr, '');
  } finally {
    rmSync(directory, { recursive: true, force: true });
  }
});
